package com.codearchive.api.settings;
public record SettingsResponse(long version, String name, String nickname, boolean copyHeader, boolean downloadHeader, boolean githubHeader,
    String downloadFilenameTemplate, String gitPathTemplate, String githubCommitMessageTemplate, String lightTheme, String darkTheme, boolean autoSyncEnabled,
    boolean githubAutoCommitEnabled, boolean githubTargetConfigured, String githubStatus, Long githubInstallationId,
    String githubOwner, String githubRepository, String githubBranch, String githubRootPath, String githubSetupUrl) {
  static SettingsResponse from(UserSettings s, boolean providerReady, String appSlug) { boolean target = s.githubTargetConfigured(); String status=!providerReady?"PROVIDER_UNAVAILABLE":!target?"TARGET_MISSING":"AVAILABLE"; String setup=appSlug!=null&&appSlug.matches("[A-Za-z0-9](?:[A-Za-z0-9-]{0,98}[A-Za-z0-9])?")?"https://github.com/apps/"+appSlug+"/installations/new":null; return new SettingsResponse(s.getVersion(), s.getDisplayName(), s.getNickname(), s.isCopyHeader(), s.isDownloadHeader(), s.isGithubHeader(), s.getDownloadFilenameTemplate(), s.getGitPathTemplate(), s.getGithubCommitMessageTemplate(), s.getLightTheme(), s.getDarkTheme(), s.isAutoSyncEnabled(), s.isGithubAutoCommitEnabled()&&providerReady, target, status, s.getGithubInstallationId(), s.getGithubOwner(), s.getGithubRepository(), s.getGithubBranch(), s.getGithubRootPath(), setup); }
}
